INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 4, 'theory', 'IP Addressing: IPv4, Masks, CIDR, NAT, and IPv6');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 4, 0, 'How many addresses are available to hosts in the network 192.168.1.0/24?', '["256", "255", "128", "254"]', 3, 'Of the 256 addresses, one is the network address (all zeros in the host part) and one is the broadcast address (all ones).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 4, 1, 'What is the network address of host 10.0.5.77 with mask /26?', '["10.0.5.64", "10.0.5.0", "10.0.5.76", "10.0.5.128"]', 0, 'Mask /26 gives blocks of 64 addresses: 0, 64, 128, 192. Address 77 lies in the block that starts at 64.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 4, 2, 'Which of these addresses are private, that is, not routed on the internet?', '["8.8.8.8 and 1.1.1.1", "100.100.100.100", "172.20.0.5 and 192.168.3.1", "224.0.0.5"]', 2, 'The private ranges are 10/8, 172.16–172.31, and 192.168/16. The other addresses are public, multicast, or provider addresses.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 4, 3, 'What does a NAT gateway do with an outgoing packet?', '["Encrypts all of it", "Replaces the sender''s address and port with its own and remembers the match", "Lowers its TTL to zero", "Turns IPv4 into IPv6"]', 1, 'The entry in the translation table lets it return the reply to the internal host.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 4, 4, 'Computer 192.168.1.10/24 sends a packet to 8.8.8.8. Who will it give the frame to?', '["Directly to the server 8.8.8.8", "The default gateway (the gateway''s MAC, destination IP 8.8.8.8)", "Any neighbor on the network", "The DHCP server"]', 1, 'The destination is outside the subnet: the MAC is the gateway''s, and the destination IP address stays the same.');
